const NodeRegistrationData_hl = makeSource(
  "module NodeRegistrationData\n\nimport {\n    TODO,\n    REQT,\n    bREQT\n} from StellarHeliosHelpers\n\nimport {\n    tx, \n    get_current_input,\n    get_current_validator_hash,\n    get_cont_outputs\n} from ScriptContext\n\nimport {\n    NodeOperatorSettings,\n    NodeOperatorSettingsV1\n} from NodeOperatorSettings\n\nenum DredNodeState {\n    NeedsValidation {\n        // datumHash: ByteArray\n        // to validate, a validator should post a Validating txn\n        // ... and add themselves to this list, using their own node-reg record id.\n        validators: []ByteArray\n    }\n    Active {\n        lastHeartbeat: Time\n    }\n    NeedsHeartbeats {\n        // datumHash: ByteArray\n        validators: []ByteArray\n    }\n    Inactive\n}\n\nstruct NodeDetailsV1 {\n    address: String\n    port: Int\n    pubKey: PubKey\n    pubKeyHash: PubKeyHash\n}\n\nstruct NodeRegistrationData {\n    id : ByteArray \"@id\" // = \"dredNode-XXXXyyyyZZZZ\"\n    type : String \"tpe\" // = \"dredNode\"\n\n    memberToken: String \"mt\"\n    state: DredNodeState \"state\"\n    nodeDetails: NodeDetailsV1 \"nd\"\n    // todo\n    // nextNodeDetails: NodeDetails \"nd'\"\n\n    func validate(self) -> Bool {\n        assert(true || /*never executed*/ self == self, \"no way\");\n        // assert(self.memberToken != null, \"memberToken is null\");\n        true\n    }\n\n    func validateCreation(self) -> Bool {\n        print(\"  -- validating creation details ...\");\n        // assert(\n        //     (self.nodeStatus.lastHeartbeat == Time::new(0)).trace(\"  -- heartbeat non-zero? \"),\n        //     \"lastHeartbeat must be 0 during creation\");\n        REQT(\"state must be NeedsValidation during creation\");\n        self.state.switch {\n            NeedsValidation{validators} => {\n                REQT(\"validators must be empty during creation\");\n                assert(\n                    (validators.length ==0).trace(\"  -- validators empty? \"),\n                    \"non-zero validators list\"\n                )\n                true\n            },\n            _ => error(\"state must be NeedsValidation during creation\")\n        } &&\n\n        self.validate()\n    }\n    func unmodifedEssentials(self, nextData: NodeRegistrationData) -> Bool {\n        REQT(\"The essential node details must be unmodified\");\n        REQT(\"rejects if nodeDetails are modified\")\n        assert(\n            (self.nodeDetails == nextData.nodeDetails).trace(\"  -- node details unchanged? \"),\n            \"nodeDetails modified\"\n        )\n\n        REQT(\"rejects if memberToken is modified\")\n        assert(\n            (self.memberToken == nextData.memberToken).trace(\"  -- memberToken unchanged? \"),\n            \"memberToken modified\"\n        )\n\n        true\n    }\n    \n    func validateUpdate(self, _nextData: NodeRegistrationData) -> Bool {\n        // TODO(\"the lastHeartbeat must be extended by settings.expectedHeartbeatInterval\");\n        assert(true || /*never executed*/ self == self, \"no way\");\n        // assert(false, \"validateUpdate() not implemented yet\");\n        true\n    }\n\n    func checkValidationActivity(self, \n        nextData: NodeRegistrationData, \n        validatorRec: NodeRegistrationData\n    ) -> Bool {\n        REQT(\"can't validate own node\");\n        validatorPkh = validatorRec.nodeDetails.pubKeyHash;\n        assert(validatorPkh != self.nodeDetails.pubKeyHash, \"can't validate own node\");\n        REQT(\"rejects unless in NeedsValidation state\");\n        oldValidators = self.state.switch {\n            NeedsValidation{validators} => {\n                print( \"   -- NeedsValidation ok\");\n                validators\n            },\n            _ => error(\"node is not in need of validation\")\n        };\n        REQT(\"rejects if the validator's id is already in the list\");\n        oldValidators.find_safe(\n            (v: ByteArray) -> Bool {  v == validatorRec.id }\n        ).switch {\n            Some => error(\"duplicate validation attempt\"),\n            None => print(\"  -- ok, additional validation from \"+ validatorRec.id.show())\n        }\n        \n        nextData.state.switch {\n            NeedsValidation{validators} => {\n                REQT(\"rejects unless the new validator's dredNode-* id is at the head of the new validators list\");\n                assert(\n                    (validators.head == validatorRec.id).trace(\"  -- new validator's id at head? \"), \n                    \"expected validator not heading the new validators list \"\n                )\n                REQT(\"rejects unless the update retains the previous validators verbatim\");\n                assert(\n                    (validators.tail == oldValidators).trace(\"  -- tail unchanged? \"),\n                    \"creator polluted the tail of validators\"\n                )\n            },\n            _ => error(\"node is not in need of validation\")\n        }\n\n        self.unmodifedEssentials(nextData)\n    }\n\n    func checkActivation(self, nextData: NodeRegistrationData, settings: NodeOperatorSettingsV1) -> Bool {\n        REQT(\"rejects unless in NeedsValidation state\");\n        self.state.switch {\n            NeedsValidation{validators} => {\n                // check mark emoji: ✅\n                print(\"  ✅ NeedsValidation: ok\");\n                needValidations = settings.minValidations;\n                validationCount = validators.length;\n                REQT(\"rejects when validations are insufficient\");\n                print(\"  -- have \"+ validationCount.show() + \" validations, need \"+ needValidations.show())\n                assert(\n                    validationCount >= needValidations,\n                    \"not enough validations to activate the node\"\n                )\n                REQT(\"rejects activation if txn is not signed by the node operator\");\n                nodePkh = self.nodeDetails.pubKeyHash;\n                print(\"  -- expecting sig from: \"+ nodePkh.show());\n                assert(\n                    tx.is_signed_by(nodePkh).trace(\"  -- txn signed by node operator? \"),\n                    \"node must activate itself\"\n                )\n            },\n            _ => error(\"node is not in need of validation\")\n        }\n        REQT(\"rejects if the node doesn't move to Active state\");\n        nextData.state.switch {\n            Active{lastHeartbeat} => {\n                print(\"  -- state is Active: ok\");\n                REQT(\"rejects if the lastHeartbeat is not updated\");\n                print(\"  -- lastHeartbeat: \"+ lastHeartbeat.show() + \" txn time: \"+ tx.time_range.show());\n                assert(\n                    tx.time_range.contains(lastHeartbeat),\n                    \"wrong heartbeat time\"\n                )\n            },\n            _ => error(\"node must switch to Active state\")\n        }\n        self.unmodifedEssentials(nextData)\n    }\n}\n\n", {
    project: "stellar-tokenomics",
    purpose: "module",
    name:  "src/nodeRegistry/NodeRegistrationData.hl", // source filename
    moduleName:  "NodeRegistrationData",
});

